        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(
                c.baseToken() == _baseToken &&
                c.nft() == _nft &&
                c.feeRate() == _feeRate &&
                c.changeFee() == _changeFee
            );
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

